using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using System.Threading;using Newtonsoft.Json.Linq;using SpatialWallpaper.Supervision.Broker;using SpatialWallpaper.Sdk.Capabilities;
namespace SpatialWallpaper.Supervision {
 public static class MiniShotSaveMigrationHost {
  static string Hash(string path){using(var file=File.OpenRead(path))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(file)).Replace("-","").ToLowerInvariant();}
  static void Safe(string path){for(path=Path.GetFullPath(path);path!=null;path=Path.GetDirectoryName(path))if(File.Exists(path)||Directory.Exists(path))if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("migration-link");}
  public static JObject Migrate(string contentRoot,string dataRoot,Guid oldWork,Guid revision,string archive){
   contentRoot=Path.GetFullPath(contentRoot);dataRoot=Path.GetFullPath(dataRoot);Safe(contentRoot);Safe(dataRoot);Safe(archive);if(oldWork==Guid.Empty||revision==Guid.Empty||oldWork==Guid.Parse(LegacyMiniShotIdentity.NativeWork)||Hash(archive)!=LegacyMiniShotIdentity.ArchiveSha256)throw new InvalidDataException("migration-original-package-identity");
   string source=Path.Combine(contentRoot,"sdk-runtime","backend","storage","live-"+oldWork.ToString("N"));var saved=PrivateStore.ReadMigrationSnapshot(source);var changes=new Dictionary<string,byte[]>(StringComparer.Ordinal);
   var allowed=Enumerable.Range(1,10).Select(i=>"minishot.v1.target-"+i.ToString("00",System.Globalization.CultureInfo.InvariantCulture)).ToArray();
   foreach(string key in saved.Keys){if(!allowed.Contains(key))throw new InvalidDataException("migration-unexpected-save-key");var value=saved.Get(key);if(!value.SequenceEqual(Encoding.UTF8.GetBytes("hit")))throw new InvalidDataException("migration-invalid-hit");changes.Add(key,value);}
   string targetRoot=Path.Combine(dataRoot,"native-private-storage");Safe(targetRoot);Guid installation=Guid.Parse(LegacyMiniShotIdentity.NativeWork);string target=Path.Combine(targetRoot,"live-"+installation.ToString("N"),"state.bin");
   var receipt=new JObject{{"format",1},{"status","pending"},{"source_work_id",oldWork.ToString("D")},{"source_revision_id",revision.ToString("D")},{"source_build_id",LegacyMiniShotIdentity.Build},{"source_archive_sha256",LegacyMiniShotIdentity.ArchiveSha256},{"source_save_sha256",saved.FileSha256},{"source_storage_version",saved.Version},{"native_work_id",LegacyMiniShotIdentity.NativeWork},{"hit_count",changes.Count},{"source_preserved",true}};
   changes.Add("migration.minishot.schema4",Encoding.UTF8.GetBytes(receipt.ToString(Newtonsoft.Json.Formatting.None)));
   string mutexKey;using(var sha=SHA256.Create())mutexKey=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(targetRoot.TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar).ToUpperInvariant()))).Replace("-","");
   using(var mutex=new Mutex(false,"Local\\SpatialWallpaper.PrivateStore."+mutexKey)){bool acquired=false;try{try{acquired=mutex.WaitOne(2000);}catch(AbandonedMutexException){acquired=true;}if(!acquired)throw new IOException("migration-storage-busy");Safe(target);if(File.Exists(target))throw new InvalidOperationException("migration-native-save-already-exists");
    using(var store=new PrivateStore(targetRoot)){var session=new BrokerSession(new AttemptReceipt(Guid.NewGuid(),Guid.NewGuid(),installation,LegacyMiniShotIdentity.Build,Guid.NewGuid(),1),false,new[]{"private-storage"});long version=store.Commit(session,0,changes);receipt["status"]="imported";receipt["native_storage_version"]=version;}
   }finally{if(acquired)mutex.ReleaseMutex();}}
   string receipts=Path.Combine(dataRoot,"save-migrations");Safe(receipts);Directory.CreateDirectory(receipts);string path=Path.Combine(receipts,Guid.NewGuid().ToString("N")+".json");try{using(var file=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.Read)){byte[] bytes=Encoding.UTF8.GetBytes(receipt.ToString());file.Write(bytes,0,bytes.Length);file.Flush(true);}receipt["receipt_file"]=path;}catch(Exception failure){receipt["receipt_warning"]=failure.GetType().Name;}
   return receipt;
  }
  public static int Run(string configuration){try{var value=JObject.Parse(File.ReadAllText(configuration));if(value.Count!=5||value.Properties().Any(p=>p.Value.Type!=JTokenType.String)||!new[]{"content_root","data_root","source_work","source_revision","archive"}.All(n=>value[n]!=null))throw new InvalidDataException("migration-configuration");Console.WriteLine(Migrate((string)value["content_root"],(string)value["data_root"],Guid.ParseExact((string)value["source_work"],"D"),Guid.ParseExact((string)value["source_revision"],"D"),(string)value["archive"]).ToString(Newtonsoft.Json.Formatting.None));return 0;}catch(Exception error){Console.WriteLine(new JObject{{"status","failed"},{"error",error.GetBaseException().Message}}.ToString(Newtonsoft.Json.Formatting.None));return 1;}}
 }
}
